CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80),email VARCHAR(120) UNIQUE,pass VARCHAR(255));
CREATE TABLE IF NOT EXISTS shipments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,tracking VARCHAR(20) UNIQUE,origin VARCHAR(80),dest VARCHAR(80),type VARCHAR(30),weight DECIMAL(8,2),speed VARCHAR(20),price DECIMAL(9,2),status TINYINT DEFAULT 0,location VARCHAR(80),eta DATE,updated DATETIME);
CREATE TABLE IF NOT EXISTS events(id INT AUTO_INCREMENT PRIMARY KEY,shipment_id INT,label VARCHAR(60),at DATETIME);
CREATE TABLE IF NOT EXISTS locations(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80),city VARCHAR(60),country VARCHAR(60),zip VARCHAR(12),address VARCHAR(120),hours VARCHAR(60));
